list_countries.code:
final response = await client.countries
    .listCountries(queryParams: {'search': 'aus'});
final countries = (response.map as Map)['countries'] as List;
for (final country in countries) {
  print('${(country as Map)['code']} ${country['name']}');
}

get_country.code:
final response = await client.countries.getCountry('AU');
final country = (response.map as Map)['country'] as Map;
print('${country['name']} ${country['state_count']}');

list_country_states.code:
final response = await client.countries
    .listCountryStates('AU', queryParams: {'limit': 3});
final states = (response.map as Map)['states'] as List;
for (final state in states) {
  print('${(state as Map)['code']} ${state['name']}');
}

get_country_state.code:
final response = await client.countries.getCountryState('AU', 'VIC');
final state = (response.map as Map)['state'] as Map;
print('${state['code']} ${state['name']}');
